function [fig, ax] = plot_sigma_curves( ...
    tauValues, sigmaCurve, ~, xTickStep)
%PLOT_SIGMA_CURVES Plot up to five boundary curves in the paper's style.
% Rows of sigmaCurve correspond to tauValues; columns correspond to A_i.
% sigmaCurve contains sigma, not sigma squared.

    tauValues = tauValues(:);
    if size(sigmaCurve, 1) ~= numel(tauValues)
        error('plot_sigma_curves:SizeMismatch', ...
            'Each row of sigmaCurve must correspond to one tau value.');
    end

    % Only this plotting copy is squared; missing/nonpositive points break lines.
    sigmaSquaredForPlot = sigmaCurve.^2;
    sigmaSquaredForPlot(~isfinite(sigmaSquaredForPlot) | ...
        sigmaSquaredForPlot <= 0) = NaN;

    colors = [
        0.0000 0.4470 0.7410
        0.8500 0.3250 0.0980
        0.9290 0.6940 0.1250
        0.4940 0.1840 0.5560
        0.4660 0.6740 0.1880
    ];
    markers = {'o', 's', 'd', '^', '+'};

    % Keep every computed line point, with markers spaced about 0.2 in tau.
    markerTau = 0:0.2:max(tauValues);
    [~, markerIndices] = min(abs(tauValues - markerTau), [], 1);
    markerIndices = unique(markerIndices);

    fig = figure('Color', 'w', 'Units', 'pixels', ...
        'Position', [100 100 968 500]);
    ax = axes('Parent', fig, 'Position', [0.198 0.180 0.733 0.720]);

    lineHandles = semilogy(ax, tauValues, sigmaSquaredForPlot, ...
        '-', 'LineWidth', 1.4);

    for aIndex = 1:size(sigmaCurve, 2)
        set(lineHandles(aIndex), ...
            'Color', colors(aIndex, :), ...
            'Marker', markers{aIndex}, ...
            'MarkerSize', 5.5, ...
            'MarkerFaceColor', colors(aIndex, :), ...
            'MarkerEdgeColor', colors(aIndex, :), ...
            'MarkerIndices', markerIndices, ...
            'DisplayName', sprintf('{\\it A}_{%d}', aIndex));
    end

    set(ax, ...
        'YScale', 'log', ...
        'XLim', [0 max(tauValues)], ...
        'YLim', [1e-4 1], ...
        'XTick', 0:xTickStep:max(tauValues), ...
        'FontName', 'Helvetica', 'FontSize', 20, ...
        'LineWidth', 1.1, 'TickDir', 'in', 'Box', 'on', ...
        'XGrid', 'on', 'YGrid', 'on', ...
        'XMinorGrid', 'off', 'YMinorGrid', 'on', ...
        'GridColor', [0 0 0], 'MinorGridColor', [0 0 0], ...
        'GridAlpha', 0.24, 'MinorGridAlpha', 0.16, ...
        'GridLineStyle', ':', 'MinorGridLineStyle', ':', ...
        'Layer', 'top');

    xlabel(ax, '\tau', ...
        'Interpreter', 'tex', 'FontSize', 22);

    ylabel(ax, '\sigma^2_{max}', ...
        'Interpreter', 'tex', 'FontSize', 22);

    legendHandle = legend(ax, lineHandles, 'Location', 'northeast', ...
        'Interpreter', 'tex', 'FontSize', 18, ...
        'LineWidth', 0.8, ...
        'Box', 'on', 'Color', 'w', 'EdgeColor', 'k');

    legendHandle.IconColumnWidth = 42;
end